[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>WellSource — Expert health guidance you can trust</title>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=DM+Sans:ital,opsz,wght@0,9..40,300;0,9..40,400;0,9..40,500;0,9..40,600;0,9..40,700;1,9..40,400&family=DM+Serif+Display:ital@0;1&display=swap" rel="stylesheet" />
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --teal: #02838D;
      --teal-dark: #016b74;
      --teal-light: #e6f5f6;
      --teal-mid: #b3dde0;
      --charcoal: #231F20;
      --gray-50: #f9fafb;
      --gray-100: #f3f4f6;
      --gray-200: #e5e7eb;
      --gray-400: #9ca3af;
      --gray-500: #6b7280;
      --gray-700: #374151;
      --coral: #e8623a;
      --amber: #f59e0b;
      --white: #ffffff;
      --font: 'DM Sans', system-ui, sans-serif;
      --font-serif: 'DM Serif Display', Georgia, serif;
      --shadow-sm: 0 1px 3px rgba(0,0,0,0.07), 0 1px 2px rgba(0,0,0,0.05);
      --shadow: 0 4px 12px rgba(0,0,0,0.08), 0 2px 4px rgba(0,0,0,0.04);
      --shadow-lg: 0 10px 30px rgba(0,0,0,0.10), 0 4px 10px rgba(0,0,0,0.05);
      --radius: 12px;
      --radius-sm: 8px;
      --radius-lg: 16px;
    }

    html { scroll-behavior: smooth; }
    body {
      font-family: var(--font);
      color: var(--charcoal);
      background: var(--white);
      font-size: 16px;
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
    }

    a { text-decoration: none; color: inherit; }
    img { display: block; max-width: 100%; }
    button { font-family: var(--font); cursor: pointer; border: none; background: none; }

    /* ===== HEADER ===== */
    .site-header {
      position: sticky;
      top: 0;
      z-index: 1000;
      background: var(--white);
      border-bottom: 1px solid var(--gray-200);
      box-shadow: var(--shadow-sm);
    }

    .header-inner {
      max-width: 1280px;
      margin: 0 auto;
      padding: 0 1.5rem;
      height: 64px;
      display: flex;
      align-items: center;
      gap: 2rem;
    }

    .logo {
      display: flex;
      align-items: center;
      gap: 0.5rem;
      flex-shrink: 0;
    }
    .logo-icon {
      width: 36px;
      height: 36px;
      background: var(--teal);
      border-radius: 8px;
      display: flex;
      align-items: center;
      justify-content: center;
    }
    .logo-icon svg { width: 20px; height: 20px; color: white; }
    .logo-text {
      font-size: 1.25rem;
      font-weight: 700;
      color: var(--charcoal);
      letter-spacing: -0.02em;
    }
    .logo-text span { color: var(--teal); }

    /* Main nav */
    .main-nav {
      display: flex;
      align-items: center;
      gap: 0.25rem;
      flex: 1;
    }

    .nav-item {
      position: relative;
    }

    .nav-trigger {
      display: flex;
      align-items: center;
      gap: 0.25rem;
      padding: 0.5rem 0.75rem;
      font-size: 0.9rem;
      font-weight: 500;
      color: var(--gray-700);
      border-radius: var(--radius-sm);
      transition: all 0.15s ease;
      white-space: nowrap;
      cursor: pointer;
      background: none;
      border: none;
      font-family: var(--font);
    }
    .nav-trigger:hover, .nav-trigger.active {
      color: var(--teal);
      background: var(--teal-light);
    }
    .nav-trigger svg {
      width: 14px;
      height: 14px;
      transition: transform 0.2s ease;
    }
    .nav-trigger.active svg { transform: rotate(180deg); }

    /* Mega dropdown */
    .mega-menu {
      position: absolute;
      top: calc(100% + 8px);
      left: 50%;
      transform: translateX(-50%);
      background: var(--white);
      border: 1px solid var(--gray-200);
      border-radius: var(--radius);
      box-shadow: var(--shadow-lg);
      padding: 1.25rem;
      min-width: 520px;
      display: none;
      z-index: 200;
    }
    .mega-menu.open { display: block; animation: fadeDown 0.18s ease-out; }

    @keyframes fadeDown {
      from { opacity: 0; transform: translateX(-50%) translateY(-6px); }
      to { opacity: 1; transform: translateX(-50%) translateY(0); }
    }

    .mega-menu-label {
      font-size: 0.7rem;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      color: var(--gray-400);
      margin-bottom: 0.625rem;
    }

    .mega-menu-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 0.25rem;
    }
    .mega-menu-grid.cols-2 { grid-template-columns: repeat(2, 1fr); }

    .mega-menu a {
      display: block;
      padding: 0.375rem 0.625rem;
      font-size: 0.875rem;
      color: var(--gray-700);
      border-radius: 6px;
      transition: all 0.12s ease;
      white-space: nowrap;
    }
    .mega-menu a:hover {
      background: var(--teal-light);
      color: var(--teal);
    }

    .mega-menu-divider { border: none; border-top: 1px solid var(--gray-200); margin: 0.875rem 0; }

    /* Header actions */
    .header-actions {
      display: flex;
      align-items: center;
      gap: 0.75rem;
      flex-shrink: 0;
    }
    .btn-ghost {
      padding: 0.5rem 1rem;
      font-size: 0.875rem;
      font-weight: 500;
      color: var(--charcoal);
      border-radius: 8px;
      transition: all 0.15s ease;
      border: 1.5px solid var(--gray-200);
    }
    .btn-ghost:hover { background: var(--gray-100); border-color: var(--gray-300); }
    .btn-primary {
      padding: 0.5rem 1.125rem;
      font-size: 0.875rem;
      font-weight: 600;
      color: var(--white);
      background: var(--teal);
      border-radius: 8px;
      transition: all 0.15s ease;
    }
    .btn-primary:hover { background: var(--teal-dark); transform: translateY(-1px); }

    /* ===== TICKER ===== */
    .ticker-bar {
      background: var(--teal);
      color: var(--white);
      overflow: hidden;
      height: 40px;
      display: flex;
      align-items: center;
    }
    .ticker-inner {
      display: flex;
      align-items: center;
      animation: ticker 28s linear infinite;
      white-space: nowrap;
    }
    .ticker-inner:hover { animation-play-state: paused; }

    @keyframes ticker {
      0% { transform: translateX(0); }
      100% { transform: translateX(-50%); }
    }

    .ticker-item {
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      font-size: 0.8125rem;
      font-weight: 500;
      padding: 0 2.5rem;
    }
    .ticker-item svg { width: 15px; height: 15px; opacity: 0.85; }
    .ticker-sep {
      width: 4px;
      height: 4px;
      border-radius: 50%;
      background: rgba(255,255,255,0.4);
      flex-shrink: 0;
    }

    /* ===== HERO ===== */
    .hero-section {
      max-width: 1280px;
      margin: 0 auto;
      padding: 2.5rem 1.5rem;
      display: grid;
      grid-template-columns: 1fr 340px;
      gap: 2rem;
      align-items: start;
    }

    .hero-main {
      position: relative;
      border-radius: var(--radius-lg);
      overflow: hidden;
      background: var(--charcoal);
      min-height: 460px;
      display: flex;
      flex-direction: column;
      justify-content: flex-end;
    }

    .hero-image {
      position: absolute;
      inset: 0;
      width: 100%;
      height: 100%;
      object-fit: cover;
      opacity: 0.65;
    }

    .hero-badge {
      position: absolute;
      top: 1.25rem;
      right: 1.25rem;
      background: var(--teal);
      color: white;
      padding: 0.375rem 0.875rem;
      border-radius: 999px;
      font-size: 0.75rem;
      font-weight: 600;
      letter-spacing: 0.04em;
      text-transform: uppercase;
      display: flex;
      align-items: center;
      gap: 0.375rem;
    }

    .hero-content {
      position: relative;
      padding: 2rem;
      background: linear-gradient(to top, rgba(0,0,0,0.85) 0%, rgba(0,0,0,0.3) 70%, transparent 100%);
    }

    .hero-category {
      display: inline-block;
      font-size: 0.75rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.1em;
      color: var(--teal-mid);
      margin-bottom: 0.625rem;
    }

    .hero-title {
      font-family: var(--font-serif);
      font-size: 2rem;
      line-height: 1.25;
      color: white;
      margin-bottom: 0.75rem;
      max-width: 600px;
    }

    .hero-subtitle {
      font-size: 0.9375rem;
      color: rgba(255,255,255,0.8);
      max-width: 540px;
      margin-bottom: 1.25rem;
    }

    .hero-cta {
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      background: var(--teal);
      color: white;
      padding: 0.625rem 1.25rem;
      border-radius: 8px;
      font-size: 0.875rem;
      font-weight: 600;
      transition: all 0.15s ease;
    }
    .hero-cta:hover { background: var(--teal-dark); }

    /* Trending sidebar */
    .hero-sidebar {
      display: flex;
      flex-direction: column;
      gap: 0;
    }

    .trending-label {
      display: flex;
      align-items: center;
      gap: 0.5rem;
      font-size: 0.75rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.1em;
      color: var(--gray-500);
      padding-bottom: 0.75rem;
      border-bottom: 2px solid var(--teal);
      margin-bottom: 0.25rem;
    }
    .trending-label svg { width: 14px; height: 14px; color: var(--coral); }

    .trending-item {
      padding: 0.875rem 0;
      border-bottom: 1px solid var(--gray-200);
      cursor: pointer;
      transition: all 0.12s ease;
    }
    .trending-item:hover .trending-headline { color: var(--teal); }

    .trending-cat {
      font-size: 0.7rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      color: var(--teal);
      margin-bottom: 0.25rem;
    }

    .trending-headline {
      font-size: 0.9rem;
      font-weight: 500;
      line-height: 1.4;
      color: var(--charcoal);
      transition: color 0.12s ease;
    }

    /* ===== NEWSLETTER CTA ===== */
    .newsletter-cta {
      background: linear-gradient(135deg, #016b74 0%, #02838D 50%, #029aa6 100%);
      padding: 3.5rem 1.5rem;
    }

    .newsletter-cta-inner {
      max-width: 680px;
      margin: 0 auto;
      text-align: center;
    }

    .newsletter-cta h2 {
      font-family: var(--font-serif);
      font-size: 2rem;
      color: white;
      margin-bottom: 0.75rem;
      line-height: 1.25;
    }

    .newsletter-cta p {
      font-size: 1rem;
      color: rgba(255,255,255,0.85);
      margin-bottom: 1.75rem;
      max-width: 520px;
      margin-left: auto;
      margin-right: auto;
    }

    .newsletter-form {
      display: flex;
      gap: 0.5rem;
      max-width: 480px;
      margin: 0 auto 0.875rem;
    }

    .newsletter-form input {
      flex: 1;
      padding: 0.75rem 1rem;
      border: none;
      border-radius: 10px;
      font-size: 0.9375rem;
      font-family: var(--font);
      outline: none;
      background: white;
    }
    .newsletter-form input::placeholder { color: var(--gray-400); }
    .newsletter-form input:focus { box-shadow: 0 0 0 3px rgba(255,255,255,0.3); }

    .btn-cta {
      padding: 0.75rem 1.5rem;
      background: var(--coral);
      color: white;
      font-size: 0.9375rem;
      font-weight: 600;
      border-radius: 10px;
      transition: all 0.15s ease;
      white-space: nowrap;
    }
    .btn-cta:hover { background: #d4532e; transform: translateY(-1px); }

    .newsletter-privacy {
      font-size: 0.75rem;
      color: rgba(255,255,255,0.6);
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 0.375rem;
    }
    .newsletter-privacy svg { width: 13px; height: 13px; }

    /* ===== HEALTH TOPICS ===== */
    .section-container {
      max-width: 1280px;
      margin: 0 auto;
      padding: 3rem 1.5rem;
    }

    .section-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      margin-bottom: 1.75rem;
    }

    .section-title {
      font-family: var(--font-serif);
      font-size: 1.625rem;
      font-weight: 400;
      color: var(--charcoal);
    }

    .view-all {
      display: inline-flex;
      align-items: center;
      gap: 0.375rem;
      font-size: 0.875rem;
      font-weight: 600;
      color: var(--teal);
      transition: gap 0.15s ease;
    }
    .view-all:hover { gap: 0.6rem; }
    .view-all svg { width: 16px; height: 16px; }

    .topics-carousel-wrapper {
      position: relative;
    }

    .topics-carousel {
      display: flex;
      gap: 1.25rem;
      overflow-x: auto;
      scroll-behavior: smooth;
      scrollbar-width: none;
      padding-bottom: 0.5rem;
    }
    .topics-carousel::-webkit-scrollbar { display: none; }

    .topic-card {
      flex-shrink: 0;
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 0.75rem;
      cursor: pointer;
      transition: transform 0.15s ease;
    }
    .topic-card:hover { transform: translateY(-4px); }

    .topic-image-wrap {
      width: 120px;
      height: 120px;
      border-radius: 50%;
      overflow: hidden;
      border: 3px solid var(--teal-mid);
      transition: border-color 0.15s ease;
      flex-shrink: 0;
    }
    .topic-card:hover .topic-image-wrap { border-color: var(--teal); }

    .topic-image-wrap img {
      width: 100%;
      height: 100%;
      object-fit: cover;
    }

    .topic-label {
      font-size: 0.875rem;
      font-weight: 600;
      text-align: center;
      color: var(--charcoal);
      max-width: 120px;
    }

    .carousel-btn {
      position: absolute;
      top: 50%;
      transform: translateY(-65%);
      width: 40px;
      height: 40px;
      border-radius: 50%;
      background: white;
      border: 1.5px solid var(--gray-200);
      box-shadow: var(--shadow);
      display: flex;
      align-items: center;
      justify-content: center;
      cursor: pointer;
      z-index: 10;
      transition: all 0.15s ease;
      color: var(--charcoal);
    }
    .carousel-btn:hover { background: var(--teal); color: white; border-color: var(--teal); }
    .carousel-btn svg { width: 16px; height: 16px; }
    .carousel-btn.prev { left: -20px; }
    .carousel-btn.next { right: -20px; }

    /* ===== TOOLS ===== */
    .tools-section {
      background: var(--gray-50);
      border-top: 1px solid var(--gray-200);
      border-bottom: 1px solid var(--gray-200);
    }

    .tools-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 2.5rem;
    }

    .tools-col-header {
      padding: 1.75rem;
      background: var(--teal);
      border-radius: var(--radius);
      margin-bottom: 1.25rem;
    }

    .tools-col-header h3 {
      font-family: var(--font-serif);
      font-size: 1.375rem;
      color: white;
      margin-bottom: 0.625rem;
    }

    .tools-col-header p {
      font-size: 0.875rem;
      color: rgba(255,255,255,0.85);
      line-height: 1.5;
      margin-bottom: 1rem;
    }

    .btn-outline-white {
      display: inline-flex;
      align-items: center;
      gap: 0.375rem;
      padding: 0.5rem 1rem;
      border: 1.5px solid rgba(255,255,255,0.6);
      border-radius: 8px;
      font-size: 0.8125rem;
      font-weight: 600;
      color: white;
      transition: all 0.15s ease;
    }
    .btn-outline-white:hover { background: rgba(255,255,255,0.15); border-color: white; }

    .tool-item {
      display: flex;
      align-items: flex-start;
      gap: 1rem;
      padding: 1rem;
      border-radius: var(--radius-sm);
      background: white;
      border: 1px solid var(--gray-200);
      margin-bottom: 0.75rem;
      transition: all 0.15s ease;
      cursor: pointer;
    }
    .tool-item:hover { border-color: var(--teal); box-shadow: var(--shadow-sm); transform: translateY(-1px); }

    .tool-icon {
      width: 42px;
      height: 42px;
      border-radius: 10px;
      background: var(--teal-light);
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
      color: var(--teal);
    }
    .tool-icon svg { width: 20px; height: 20px; }

    .tool-info h4 {
      font-size: 0.9375rem;
      font-weight: 600;
      color: var(--charcoal);
      margin-bottom: 0.25rem;
    }
    .tool-info p {
      font-size: 0.8125rem;
      color: var(--gray-500);
      line-height: 1.4;
    }

    .tool-arrow {
      margin-left: auto;
      color: var(--gray-400);
      align-self: center;
      flex-shrink: 0;
      transition: all 0.15s ease;
    }
    .tool-item:hover .tool-arrow { color: var(--teal); transform: translateX(3px); }
    .tool-arrow svg { width: 16px; height: 16px; }

    /* ===== RECOMMENDED READS ===== */
    .reads-tabs {
      display: flex;
      gap: 0;
      border-bottom: 2px solid var(--gray-200);
      margin-bottom: 1.75rem;
      overflow-x: auto;
      scrollbar-width: none;
    }
    .reads-tabs::-webkit-scrollbar { display: none; }

    .tab-btn {
      padding: 0.625rem 1.125rem;
      font-size: 0.875rem;
      font-weight: 500;
      color: var(--gray-500);
      border-bottom: 2px solid transparent;
      margin-bottom: -2px;
      transition: all 0.15s ease;
      white-space: nowrap;
      background: none;
      border-left: none;
      border-right: none;
      border-top: none;
      font-family: var(--font);
      cursor: pointer;
    }
    .tab-btn:hover { color: var(--teal); }
    .tab-btn.active {
      color: var(--teal);
      border-bottom-color: var(--teal);
      font-weight: 600;
    }

    .articles-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 1.25rem;
    }

    .article-card {
      border-radius: var(--radius);
      overflow: hidden;
      background: white;
      border: 1px solid var(--gray-200);
      transition: all 0.2s ease;
      cursor: pointer;
    }
    .article-card:hover {
      box-shadow: var(--shadow);
      transform: translateY(-3px);
      border-color: var(--teal-mid);
    }

    .article-image {
      width: 100%;
      height: 170px;
      object-fit: cover;
    }

    .article-body {
      padding: 1rem;
    }

    .article-cat {
      font-size: 0.7rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      color: var(--teal);
      margin-bottom: 0.375rem;
    }

    .article-title {
      font-size: 0.9375rem;
      font-weight: 600;
      line-height: 1.4;
      color: var(--charcoal);
      margin-bottom: 0.5rem;
    }

    .article-meta {
      font-size: 0.75rem;
      color: var(--gray-400);
      display: flex;
      align-items: center;
      gap: 0.375rem;
    }
    .article-meta svg { width: 12px; height: 12px; }
    .reviewed-badge {
      display: inline-flex;
      align-items: center;
      gap: 0.25rem;
      font-size: 0.7rem;
      color: var(--teal);
      font-weight: 500;
    }
    .reviewed-badge svg { width: 11px; height: 11px; }

    /* ===== TRUST PILLARS ===== */
    .trust-section {
      background: linear-gradient(135deg, #f0fafa 0%, #e6f5f6 100%);
      border-top: 1px solid var(--teal-mid);
    }

    .trust-header {
      text-align: center;
      margin-bottom: 2.5rem;
    }

    .trust-header h2 {
      font-family: var(--font-serif);
      font-size: 1.875rem;
      color: var(--charcoal);
      max-width: 520px;
      margin: 0 auto;
      line-height: 1.3;
    }

    .trust-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 1.5rem;
    }

    .trust-pillar {
      text-align: center;
      padding: 1.75rem 1.25rem;
      background: white;
      border-radius: var(--radius);
      border: 1px solid var(--teal-mid);
      transition: all 0.2s ease;
    }
    .trust-pillar:hover { box-shadow: var(--shadow); transform: translateY(-3px); }

    .trust-icon {
      width: 56px;
      height: 56px;
      border-radius: 14px;
      background: var(--teal-light);
      display: flex;
      align-items: center;
      justify-content: center;
      margin: 0 auto 1rem;
      color: var(--teal);
    }
    .trust-icon svg { width: 26px; height: 26px; }

    .trust-pillar h3 {
      font-size: 1rem;
      font-weight: 700;
      color: var(--charcoal);
      margin-bottom: 0.5rem;
    }

    .trust-pillar p {
      font-size: 0.85rem;
      color: var(--gray-500);
      line-height: 1.55;
    }

    /* ===== FEATURED PROGRAMS ===== */
    .programs-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 1.25rem;
    }

    .program-card {
      border-radius: var(--radius);
      overflow: hidden;
      background: white;
      border: 1px solid var(--gray-200);
      transition: all 0.2s ease;
      cursor: pointer;
    }
    .program-card:hover { box-shadow: var(--shadow); transform: translateY(-3px); }

    .program-image {
      width: 100%;
      height: 150px;
      object-fit: cover;
    }

    .program-body {
      padding: 1rem;
    }

    .program-label {
      font-size: 0.7rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      color: var(--gray-400);
      margin-bottom: 0.375rem;
    }

    .program-title {
      font-size: 0.9375rem;
      font-weight: 600;
      color: var(--charcoal);
      line-height: 1.4;
    }

    /* ===== LATEST VIDEOS ===== */
    .videos-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 1.25rem;
    }

    .video-card {
      border-radius: var(--radius);
      overflow: hidden;
      cursor: pointer;
      transition: all 0.2s ease;
    }
    .video-card:hover { transform: translateY(-3px); }

    .video-thumb {
      position: relative;
      border-radius: var(--radius);
      overflow: hidden;
      margin-bottom: 0.875rem;
    }

    .video-thumb img {
      width: 100%;
      height: 140px;
      object-fit: cover;
      display: block;
    }

    .play-btn {
      position: absolute;
      inset: 0;
      display: flex;
      align-items: center;
      justify-content: center;
      background: rgba(0,0,0,0.3);
      transition: background 0.15s ease;
    }
    .video-card:hover .play-btn { background: rgba(0,0,0,0.45); }

    .play-circle {
      width: 44px;
      height: 44px;
      border-radius: 50%;
      background: rgba(255,255,255,0.9);
      display: flex;
      align-items: center;
      justify-content: center;
      transition: transform 0.15s ease;
    }
    .video-card:hover .play-circle { transform: scale(1.1); }
    .play-circle svg { width: 18px; height: 18px; color: var(--teal); margin-left: 2px; }

    .video-cat {
      font-size: 0.7rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      color: var(--teal);
      margin-bottom: 0.25rem;
    }

    .video-title {
      font-size: 0.875rem;
      font-weight: 600;
      color: var(--charcoal);
      line-height: 1.4;
    }

    /* ===== FOOTER ===== */
    .footer-newsletter {
      background: var(--charcoal);
      padding: 3rem 1.5rem;
    }

    .footer-newsletter-inner {
      max-width: 680px;
      margin: 0 auto;
      text-align: center;
    }

    .footer-newsletter h3 {
      font-family: var(--font-serif);
      font-size: 1.5rem;
      color: white;
      margin-bottom: 0.75rem;
    }

    .footer-newsletter p {
      font-size: 0.9rem;
      color: rgba(255,255,255,0.65);
      margin-bottom: 1.5rem;
      line-height: 1.6;
    }

    .footer-newsletter-form {
      display: flex;
      gap: 0.5rem;
