    .btn-teal:hover { background: var(--teal-dark); }

    .site-footer {
      background: #1a1617;
      padding: 2rem 1.5rem;
    }

    .footer-inner {
      max-width: 1280px;
      margin: 0 auto;
    }

    .footer-logo {
      display: flex;
      align-items: center;
      gap: 0.5rem;
      margin-bottom: 1.25rem;
    }
    .footer-logo-icon {
      width: 30px;
      height: 30px;
      background: var(--teal);
      border-radius: 7px;
      display: flex;
      align-items: center;
      justify-content: center;
